from pathlib import Path
import json
p=Path('artifacts/evidence/TI2R_SOLUTE_HOLDOUT')
m=json.loads((p/'frozen-manifest.json').read_text())
originals={k:json.loads(Path(v).read_text()) for k,v in {'v1':'configs/registration/ti2r-solute-direct-method.json','v2':'configs/registration/ti2r-solute-v2-method.json'}.items()}
changes=[]
def compare(a,b,path):
 if type(a) is not type(b):
  changes.append({'field':path,'frozen_file_type':type(a).__name__,'manifest_type':type(b).__name__,'frozen_file_value':a,'manifest_value':b})
 elif isinstance(a,dict):
  for key in a: compare(a[key],b[key],path+'.'+key)
 elif isinstance(a,list):
  for index,(x,y) in enumerate(zip(a,b)):compare(x,y,path+f'[{index}]')
 elif a!=b:
  changes.append({'field':path,'frozen_file_value':a,'manifest_value':b})
compare(originals,m['configurations'],'configurations')
print(json.dumps({'incident':'CONFIGURATION_DIVERGENCE','text_only_differences':changes,'experimental_reads':0,'repair_performed':False,'retry_performed':False},indent=2))
